def merge_intervals(intervals):
    """Merge closed integer intervals; return sorted, non-overlapping [start, end] lists.

    Intervals sharing an endpoint merge ([1,3] + [3,5] -> [1,5]); a gap of 1 does not.
    The input list and its pairs are not modified.
    Time O(n log n) for the sort, extra space O(n) for the output.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: p[0]):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
EOF
