def merge_intervals(intervals):
    """Merge overlapping closed integer intervals.

    Intervals sharing an endpoint ([1,3] and [3,5]) are merged; adjacent but
    disjoint ones ([1,3] and [4,5]) are not. The input list and its pairs are
    not modified. Returns a new sorted list of [start, end] lists.

    Time: O(n log n) for the sort; space: O(n) for the sorted copy and result.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: p[0]):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
