'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { TTLCache } = require('../src/solution.cjs');

function setup() {
  let t = 1000;
  const clock = { now: () => t, advance: (ms) => { t += ms; } };
  return { clock, cache: new TTLCache(clock.now) };
}

test('returns value before expiry', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.advance(99);
  assert.strictEqual(cache.get('a'), 1);
});

test('expires exactly at the expiry instant and removes entry', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.advance(100);
  assert.strictEqual(cache.get('a'), undefined);
