from collections import deque


def topological_order(nodes, edges):
    """Return a valid topological order of nodes; raise ValueError on a cycle.

    Kahn's algorithm. Duplicate edges are collapsed so they cannot skew
    in-degrees. Inputs are not mutated. Time O(V + E), space O(V + E).
    """
    successors = {n: set() for n in nodes}
    for a, b in edges:
        successors[a].add(b)

    indegree = {n: 0 for n in nodes}
    for succ in successors.values():
        for b in succ:
            indegree[b] += 1

    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for b in successors[n]:
            indegree[b] -= 1
            if indegree[b] == 0:
                queue.append(b)

    if len(order) != len(indegree):
        raise ValueError("graph contains a cycle")
    return order
