from collections import deque


def topological_order(nodes, edges):
    """Return an order of `nodes` in which every edge (a, b) has a before b.

    Raises ValueError if the edges contain a cycle (including self-loops).
    Inputs are not mutated. Time O(V + E), space O(V + E).
    """
    succ = {n: set() for n in nodes}  # set dedupes repeated edges
    for a, b in edges:
        succ[a].add(b)
    indegree = dict.fromkeys(succ, 0)
    for targets in succ.values():
        for b in targets:
            indegree[b] += 1

    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for b in succ[n]:
            indegree[b] -= 1
            if indegree[b] == 0:
                queue.append(b)

    if len(order) != len(succ):
        raise ValueError("graph contains a cycle")
    return order
