def topological_order(nodes, edges):
    """Return a topological ordering of nodes (Kahn's algorithm).

    Raises ValueError if the graph has a cycle (including self-loops).
    Inputs are not mutated. Duplicate edges are ignored.
    """
    successors = {n: set() for n in nodes}
    indegree = {n: 0 for n in nodes}
    for a, b in edges:
        if b not in successors[a]:
            successors[a].add(b)
            indegree[b] += 1

    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in successors[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                queue.append(m)

    if len(order) != len(indegree):
        raise ValueError("graph contains a cycle")
    return order

