import re

_AGE_RE = re.compile(r"[0-9]+")


def _parse_csv(text):
    """Strict CSV parser: returns a list of rows (lists of str).

    Quotes are only allowed around a whole field; a quote inside an unquoted
    field, text after a closing quote, or an unterminated quote is an error.
    Records end with \\n, \\r\\n or \\r; a final terminator adds no empty row.
    """
    rows, row, field = [], [], []
    state = "start"  # start | plain | quoted | closed
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        i += 1
        if state == "quoted":
            if c == '"':
                if i < n and text[i] == '"':
                    field.append('"')
                    i += 1
                else:
                    state = "closed"
            else:
                field.append(c)
            continue
        if c == ",":
            row.append("".join(field))
            field = []
            state = "start"
        elif c in "\r\n":
            if c == "\r" and i < n and text[i] == "\n":
                i += 1
            row.append("".join(field))
            rows.append(row)
            row, field, state = [], [], "start"
        elif state == "closed":
            raise ValueError("invalid CSV: data after closing quote")
        elif c == '"':
            if state != "start":
                raise ValueError("invalid CSV: quote inside unquoted field")
            state = "quoted"
        else:
            field.append(c)
            state = "plain"
    if state == "quoted":
        raise ValueError("invalid CSV: unterminated quote")
    if state != "start" or field or row:
        row.append("".join(field))
        rows.append(row)
    return rows


def read_people(text):
    """Parse CSV text with header name,age into [{"name": str, "age": int}, ...]."""
    rows = _parse_csv(text)
    if not rows or rows[0] != ["name", "age"]:
        raise ValueError("header must be exactly: name,age")
    people = []
    for num, row in enumerate(rows[1:], start=2):
        if len(row) != 2:
            raise ValueError("record %d: expected 2 columns, got %d" % (num, len(row)))
        name, age = row
        if not _AGE_RE.fullmatch(age):
            raise ValueError("record %d: invalid age %r" % (num, age))
        age = int(age)
        if age > 130:
            raise ValueError("record %d: age out of range" % num)
        people.append({"name": name, "age": age})
    return people
