                if i >= n:
                    raise ValueError("unterminated quoted field")
                if text[i] == '"':
                    if text[i + 1:i + 2] == '"':
                        chars.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                chars.append(text[i])
                i += 1
            if i < n and text[i] not in ",\r\n":
                raise ValueError("characters after closing quote")
            field = "".join(chars)
        else:
            start = i
            while i < n and text[i] not in ',"\r\n':
                i += 1
            if i < n and text[i] == '"':
                raise ValueError("quote inside unquoted field")
            field = text[start:i]
        row.append(field)
        # Parse the delimiter following the field.
        if i >= n:
            break
        if text[i] == ",":
            i += 1
            if i >= n:  # trailing comma at EOF: one more empty field
                row.append("")
            continue
        i += 2 if text.startswith("\r\n", i) else 1
        rows.append(row)
        row = []
    if row:
        rows.append(row)
    return rows


def read_people(text):
    """Parse CSV text with header name,age into a list of dicts."""
    rows = _parse_csv(text)
    if not rows or rows[0] != ["name", "age"]:
        raise ValueError("header must be exactly name,age")
    people = []
    for row in rows[1:]:
        if len(row) != 2:
            raise ValueError(f"expected 2 columns, got {len(row)}")
        name, age = row
        if not _AGE_RE.fullmatch(age) or int(age) > 130:
            raise ValueError(f"invalid age: {age!r}")
        people.append({"name": name, "age": int(age)})
    return people
