'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Throws on unsafe own keys at any depth (including inside arrays), on
// non-JSON-like objects, and on cycles.
function validate(value, ancestors = new Set()) {
  if (value === null || typeof value !== 'object') return;
  if (ancestors.has(value)) throw new TypeError('mergeConfig: circular structure');
  const isArray = Array.isArray(value);
  if (!isArray && !isPlainObject(value)) {
    throw new TypeError('mergeConfig: only plain objects and arrays are supported');
  }
  ancestors.add(value);
  for (const key of Object.getOwnPropertyNames(value)) {
    if (UNSAFE_KEYS.has(key)) throw new TypeError(`mergeConfig: unsafe key "${key}"`);
    if (isArray && key === 'length') continue;
    validate(value[key], ancestors);
  }
  ancestors.delete(value);
}

// Assumes validated input.
function clone(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return Array.from(value, clone);
  const out = {};
  for (const key of Object.keys(value)) out[key] = clone(value[key]);
  return out;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return clone(override);
  const out = {};
  for (const key of Object.keys(base)) {
    out[key] = Object.prototype.hasOwnProperty.call(override, key)
      ? merge(base[key], override[key])
      : clone(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.prototype.hasOwnProperty.call(base, key)) out[key] = clone(override[key]);
  }
  return out;
}

function mergeConfig(base, override) {
  validate(base);
  validate(override);
  return merge(base, override);
}

module.exports = { mergeConfig };
