'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Deep-copies a JSON-like value, rejecting unsafe own keys at any depth.
function clone(value, path, ancestors) {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'function' || typeof value === 'symbol') {
      throw new TypeError(`Unsupported value at ${path}`);
    }
    return value;
  }
  const isArray = Array.isArray(value);
  if (!isArray && !isPlainObject(value)) {
    throw new TypeError(`Unsupported value at ${path}`);
  }
  if (ancestors.has(value)) throw new TypeError(`Circular reference at ${path}`);
  ancestors.add(value);
  let out;
  if (isArray) {
    out = new Array(value.length);
    for (let i = 0; i < value.length; i++) {
      if (i in value) out[i] = clone(value[i], `${path}[${i}]`, ancestors);
    }
  } else {
    out = {};
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new Error(`Unsafe key "${key}" at ${path}`);
    }
    for (const key of Object.keys(value)) {
      out[key] = clone(value[key], `${path}.${key}`, ancestors);
    }
  }
  ancestors.delete(value);
  return out;
}

function merge(base, override, path) {
  if (isPlainObject(base) && isPlainObject(override)) {
    const out = {};
    for (const key of Object.keys(base)) {
      if (!Object.prototype.hasOwnProperty.call(override, key)) {
        out[key] = clone(base[key], `${path}.${key}`, new Set());
      }
    }
    for (const key of Object.keys(override)) {
      out[key] = Object.prototype.hasOwnProperty.call(base, key)
        ? merge(base[key], override[key], `${path}.${key}`)
        : clone(override[key], `${path}.${key}`, new Set());
    }
    return out;
  }
  // Replacement: override wins, but base was still validated up front.
  return clone(override, path, new Set());
}

function mergeConfig(base, override) {
  // Validate both inputs completely first so nothing unsafe is ever skipped
  // (e.g. inside a base subtree that gets replaced) and errors precede any work.
  clone(base, 'base', new Set());
  clone(override, 'override', new Set());
  return merge(base, override, '$');
}

module.exports = { mergeConfig };
