'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Validates and deep-copies a value in one pass.
function clone(value, seen) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) throw new TypeError('mergeConfig: circular structure');
  seen.add(value);
  let out;
  if (Array.isArray(value)) {
    out = new Array(value.length);
    for (let i = 0; i < value.length; i++) {
      if (i in value) out[i] = clone(value[i], seen);
    }
  } else if (isPlainObject(value)) {
    out = {};
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`mergeConfig: unsafe key "${key}"`);
      }
      out[key] = clone(value[key], seen);
    }
  } else {
    throw new TypeError('mergeConfig: unsupported non-plain object');
  }
  seen.delete(value);
  return out;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return override;
  const out = {};
  for (const key of Object.keys(base)) out[key] = base[key];
  for (const key of Object.keys(override)) {
    out[key] = key in out && Object.hasOwn(base, key)
      ? merge(base[key], override[key])
      : override[key];
  }
  return out;
}

function mergeConfig(base, override) {
  // Cloning both inputs first validates them fully and guarantees no sharing.
  const b = clone(base, new Set());
  const o = clone(override, new Set());
  return merge(b, o);
}

module.exports = { mergeConfig };
