'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Deep-copies a JSON-like value, rejecting unsafe keys and unsupported types.
function cloneSafe(value, stack) {
  if (value === null || typeof value !== 'object') return value;
  if (stack.has(value)) throw new TypeError('mergeConfig: circular reference');
  const isArr = Array.isArray(value);
  if (!isArr && !isPlainObject(value)) {
    throw new TypeError('mergeConfig: unsupported non-plain object');
  }
  stack.add(value);
  let out;
  if (isArr) {
    out = new Array(value.length);
    for (let i = 0; i < value.length; i++) out[i] = cloneSafe(value[i], stack);
  } else {
    out = {};
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new TypeError(`mergeConfig: unsafe key "${key}"`);
      out[key] = cloneSafe(value[key], stack);
    }
  }
  stack.delete(value);
  return out;
}

function mergeClean(base, override) {
  // base and override are already validated clones, so they can be reused directly.
  for (const key of Object.keys(override)) {
    if (isPlainObject(base[key]) && isPlainObject(override[key])) {
      base[key] = mergeClean(base[key], override[key]);
    } else {
      base[key] = override[key];
    }
  }
  return base;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    throw new TypeError('mergeConfig: both arguments must be plain objects');
  }
  // Validate and copy both inputs up front so the result shares nothing with them.
  const baseCopy = cloneSafe(base, new Set());
  const overrideCopy = cloneSafe(override, new Set());
  return mergeClean(baseCopy, overrideCopy);
}

module.exports = { mergeConfig };

