'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    sum += w;
    if (!Number.isSafeInteger(sum) || !Number.isSafeInteger(total * w)) {
      throw new RangeError('values exceed the safe integer range');
    }
  }

  // Exact integer arithmetic: quota_i = total * w_i / sum, split into
  // floor ((t - rem) / sum) and remainder rem = t % sum, both exact.
  const result = new Array(weights.length);
  const rems = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const t = total * weights[i];
    const rem = t % sum;
    rems[i] = rem;
    result[i] = (t - rem) / sum;
    allocated += result[i];
  }

  const order = rems.map((_, i) => i).sort((a, b) => rems[b] - rems[a] || a - b);
  for (let k = 0; k < total - allocated; k++) result[order[k]] += 1;
  return result;
}

module.exports = { splitCents };
