from datetime import datetime, timezone


def utc_day_start(text):
    """Return UTC midnight of the UTC day containing the ISO 8601 instant `text`.

    `text` must carry an explicit offset (`Z` or `+HH:MM`/`-HH:MM`).
    Naive or invalid input raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    # datetime.fromisoformat only accepts "Z" from Python 3.11 on.
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)  # raises ValueError on bad input
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError("timestamp must include an explicit UTC offset")
    utc = dt.astimezone(timezone.utc)
    return utc.replace(hour=0, minute=0, second=0, microsecond=0)
