'use strict';

const VERSION = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parse(v) {
  if (typeof v !== 'string') throw new TypeError('version must be a string');
  const m = VERSION.exec(v);
  if (!m) throw new TypeError('malformed version: ' + v);
  return m.slice(1);
}

// Components have no leading zeros, so a longer digit string is larger and
// equal-length strings compare lexicographically. Exact for any magnitude.
function compareComponent(x, y) {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const c = compareComponent(pa[i], pb[i]);
    if (c !== 0) return c;
  }
  return 0;
}

module.exports = { compareVersion };
