const VERSION_PATTERN = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parse(version) {
  if (typeof version !== 'string') {
    throw new TypeError('Version must be a string');
  }
  const match = VERSION_PATTERN.exec(version);
  if (match === null) {
    throw new TypeError(`Invalid version string: ${version}`);
  }
  return [match[1], match[2], match[3]];
}

// Components have no leading zeros, so a longer string is a larger number
// and equal-length strings compare correctly lexicographically.
function compareComponent(x, y) {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const c = compareComponent(pa[i], pb[i]);
    if (c !== 0) return c;
  }
  return 0;
}

module.exports = { compareVersion };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { compareVersion } = require('./solution.cjs');

test('numeric, not lexicographic, ordering', () => {
  assert.equal(compareVersion('1.10.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.9', '1.10.0'), -1);
  assert.equal(compareVersion('2.0.0', '10.0.0'), -1);
});

test('huge components', () => {
  const big = '9007199254740993'; // MAX_SAFE_INTEGER + 2
  const big2 = '9007199254740992';
  assert.equal(compareVersion(`1.${big}.0`, `1.${big2}.0`), 1);
  assert.equal(compareVersion(`1.${big2}.0`, `1.${big}.0`), -1);
  assert.equal(compareVersion(`1.0.${big}`, `1.0.${big}`), 0);
  const huge = '1' + '0'.repeat(50);
