class Emitter {
  constructor() {
    this._listeners = new Map();
  }

  on(event, fn) {
    let set = this._listeners.get(event);
    if (!set) {
      set = new Set();
      this._listeners.set(event, set);
    }
    set.add(fn);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      this.off(event, fn);
    };
  }

  off(event, fn) {
    const set = this._listeners.get(event);
    if (!set) return;
    set.delete(fn);
    if (set.size === 0) this._listeners.delete(event);
  }

  emit(event, value) {
    const set = this._listeners.get(event);
    if (!set) return;
    for (const fn of [...set]) fn(value);
  }
}

module.exports = { Emitter };
EOF
cat > test/solution.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert');
const { Emitter } = require('../src/solution.cjs');

test('calls listeners in registration order, events independent', () => {
  const e = new Emitter();
  const calls = [];
  e.on('a', (v) => calls.push('1' + v));
  e.on('a', (v) => calls.push('2' + v));
  e.on('b', (v) => calls.push('b' + v));
  e.emit('a', 'x');
  assert.deepStrictEqual(calls, ['1x', '2x']);
});

test('listener registered at most once per event', () => {
  const e = new Emitter();
  let n = 0;
  const f = () => n++;
  e.on('a', f);
  e.on('a', f);
  e.emit('a');
  assert.strictEqual(n, 1);
});

test('removal during emit affects only later emits', () => {
  const e = new Emitter();
  const calls = [];
  const second = () => calls.push('second');
  e.on('a', () => { calls.push('first'); e.off('a', second); });
