from pathlib import Path, PurePosixPath, PureWindowsPath


def resolve_upload(root, supplied):
    """Resolve an untrusted relative path to a location strictly inside root.

    Existing symlinks are followed, so a link pointing outside root is
    rejected. The target need not exist. Nothing is created. Raises
    ValueError for absolute paths, root itself, or escapes from root.

    This is a point-in-time check: it cannot stop a symlink race (TOCTOU).
    """
    if not isinstance(supplied, str):
        raise ValueError("path must be a string")
    if "\0" in supplied:
        raise ValueError("path contains a null byte")
    if PurePosixPath(supplied).is_absolute() or PureWindowsPath(supplied).anchor:
        raise ValueError("absolute paths are not allowed")

    real_root = Path(root).resolve(strict=True)
    if not real_root.is_dir():
        raise ValueError("root is not a directory")

    # resolve(strict=False) follows existing symlinks and normalizes "..";
    # components that do not exist are kept as-is.
    target = (real_root / supplied).resolve(strict=False)

    if target == real_root:
        raise ValueError("path must not be the root itself")
    if real_root not in target.parents:
        raise ValueError("path escapes the root directory")
    return target
